typedef unsigned char uint8;
typedef float rational_t;
typedef float vm_num_t;

class stringx
{
protected:
  char *chars;
  void *my_buf;

public:
  stringx(const stringx &cp);
  ~stringx();
};

class color
{
public:
  rational_t r, g, b, a;
};

enum text_widget_justification
{
  JUSTIFY_LEFT = 0,
  JUSTIFY_CENTER,
  JUSTIFY_RIGHT
};

class text_block_widget
{
public:
  class block_info_t
  {
  public:
    block_info_t();
    rational_t scale;
    text_widget_justification just;
    stringx typeface;
    uint8 max_lines;
    short line_spacing;
    short max_width;
    stringx break_substring;
    stringx text;
    color col;
  };

  void set_block_info(block_info_t *info_ptr);
  const block_info_t &get_block_info() const;
};

typedef text_block_widget* vm_text_block_widget_t;

class vm_stack
{
public:
  int salloc;
  char* buffer;
  char* SP;

private:
  void *my_thread;

protected:
  void move_SP(int n)
  {
    SP += n;
  }

public:
  char* get_SP() const { return SP; }
  void pop(int n) { move_SP(-n); }
};

class script_library_class
{
public:
  class function
  {
  public:
    enum entry_t
    {
      FIRST_ENTRY,
      RECALL_ENTRY
    };

  protected:
    char* name;

  public:
    function(script_library_class* slc, const char* n);

  protected:
    virtual ~function();

  public:
    virtual bool operator()(vm_stack& stack, entry_t entry) { return true; }
  };
};

class slf_text_block_widget_set_max_lines_t : public script_library_class::function
{
public:
  slf_text_block_widget_set_max_lines_t(script_library_class* slc,const char* n) : script_library_class::function(slc,n) {}
  struct parms_t
  {
    vm_text_block_widget_t me;
    vm_num_t val;
  };

  virtual bool operator()(vm_stack& stack,entry_t entry)
  {
    stack.pop(sizeof(parms_t));
    parms_t* parms = (parms_t*)stack.get_SP();

    text_block_widget::block_info_t info = parms->me->get_block_info();
    info.max_lines = (uint8)parms->val;

    parms->me->set_block_info(&info);

    return true;
  }
};
